    module = request.match_info["module"]
    path = request.match_info["path"]

    engine = get_engine()
    workflow = engine.get_workflow(f"{module}/{path}")

    if "error" in workflow:
        return web.json_response(workflow, status=404)

    return web.json_response(workflow)


